t=np.arange(12);mid=np.full(12,100.);trade=np.array([100.1,99.9,100.1,99.9,100.1,100.1,99.9,100.1,99.9,100.1,99.9,100.1]);ax.plot(t,mid,color=GOOD,lw=2,label='efficient mid (USD)');ax.step(t,trade,where='mid',color=BAD,lw=2,label='trade price (USD)');ax.axhline(99.9,color=MUTED,ls=':');ax.axhline(100.1,color=MUTED,ls=':');ax.set_xlabel('minute');ax.set_ylabel('price (USD)');ax.set_title('A trade can move even when the mid does not',loc='left');ax.legend(fontsize=7)
